@Override
public synchronized void restoreReference(
        io.github.diodeme.ji.artifact.ArtifactReferenceEntry entry, Instant now) {
    io.github.diodeme.ji.artifact.ArtifactReference reference = entry.reference();
    ReferenceMetadata existing = references.get(entry.referenceId());
    if (existing != null) {
        if (!existing.publicValue().equals(reference)) {
            throw error("artifact.store_unavailable", Map.of("referenceId", entry.referenceId()));
        }
        return;
    }
    ObjectMetadata object = metadata.get(reference.artifactId());
    Path path = objectPath(reference.artifactId());
    try {
        if (!Files.isRegularFile(path) || Files.size(path) != reference.size()) {
            throw error("artifact.missing", Map.of("artifactId", reference.artifactId().value()));
        }
    } catch (IOException failure) {
        throw error("artifact.store_unavailable", Map.of("artifactId", reference.artifactId().value()), failure);
    }
    if (object == null) {
        object = new ObjectMetadata(reference.artifactId(), reference.mediaType(), reference.size());
        metadata.put(reference.artifactId(), object);
    } else if (object.size != reference.size() || !object.mediaType.equals(reference.mediaType())) {
        throw error("artifact.store_unavailable", Map.of("artifactId", reference.artifactId().value()));
    }
    references.put(entry.referenceId(), new ReferenceMetadata(entry.referenceId(), reference.artifactId(),
            reference.scope(), reference.mediaType(), reference.size(), reference.displayName()));
    object.orphanedAt = null;
    saveState();
}

